@using System.Threading
@inject IProductService ProductService
@implements IDisposable

<div class="product-search">
    <input type="text"
           placeholder="Search products…"
           @oninput="OnSearchInput"
           value="@_query" />

    @if (_loading)
    {
        <div class="product-search-status">Searching…</div>
    }
    else if (_error is not null)
    {
        <div class="product-search-status product-search-error">
            Something went wrong. Please try again.
        </div>
    }
    else if (_searched && _results.Count == 0)
    {
        <div class="product-search-status">No products found.</div>
    }

    @if (_results.Count > 0)
    {
        <div class="product-search-results">
            @foreach (var product in _results)
            {
                <div class="product-card" @onclick="() => SelectProduct(product)">
                    <img src="@product.ImageUrl" alt="@product.Name" loading="lazy" />
                    <div class="product-card-body">
                        <h3>@product.Name</h3>
                        <p>@product.Price.ToString("C")</p>
                    </div>
                </div>
            }
        </div>
    }
</div>

@code {
    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    private string _query = string.Empty;
    private List<Product> _results = new();
    private bool _loading;
    private bool _searched;
    private Exception? _error;

    private Timer? _debounceTimer;
    private CancellationTokenSource? _searchCts;

    private void OnSearchInput(ChangeEventArgs e)
    {
        _query = e.Value?.ToString() ?? string.Empty;

        // Cancel any in-flight search immediately so it doesn't overwrite
        // results from the newer query.
        CancelPendingSearch();

        _debounceTimer?.Dispose();
        var captured = _query;
        _debounceTimer = new Timer(_ =>
        {
            _ = InvokeAsync(() => ExecuteSearchAsync(captured));
        }, null, 300, Timeout.Infinite);
    }

    private async Task ExecuteSearchAsync(string query)
    {
        if (string.IsNullOrWhiteSpace(query))
        {
            _results = new();
            _searched = false;
            _error = null;
            _loading = false;
            StateHasChanged();
            return;
        }

        _loading = true;
        _error = null;
        StateHasChanged();

        var cts = new CancellationTokenSource();
        _searchCts = cts;

        try
        {
            var results = await ProductService.SearchAsync(query, cts.Token);

            // Only apply results if this search wasn't cancelled.
            if (!cts.Token.IsCancellationRequested)
            {
                _results = results;
                _searched = true;
                _error = null;
            }
        }
        catch (OperationCanceledException)
        {
            // Search was superseded by a newer query — nothing to do.
        }
        catch (Exception ex)
        {
            if (!cts.Token.IsCancellationRequested)
            {
                _error = ex;
                _results = new();
            }
        }
        finally
        {
            if (_searchCts == cts)
            {
                _loading = false;
            }
            cts.Dispose();
            StateHasChanged();
        }
    }

    private async Task SelectProduct(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }

    private void CancelPendingSearch()
    {
        _searchCts?.Cancel();
        _searchCts?.Dispose();
        _searchCts = null;
    }

    public void Dispose()
    {
        _debounceTimer?.Dispose();
        CancelPendingSearch();
    }
}

